/** Self-service, or anyone who may change the target's role. */
function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

function isAwayAt(absence: MemberAbsence, at: Date): boolean {
  const now = at.getTime();
  return (
    new Date(absence.startsAt).getTime() <= now &&
    now < new Date(absence.endsAt).getTime()
  );
}

export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);
  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("An absence must end after it starts");
  }
  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
  });
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);
  await memberRepo.deleteAbsence(orgId, userId);
}

export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", { kind: "organization", orgId });
  await requireActiveMember(orgId, userId);

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence) return null;
  if (new Date(absence.endsAt).getTime() <= Date.now()) return null;
  return absence;
}

/**
 * The delegate standing in for `userId` at `at`, or null when they are not
 * away or named nobody. Never chained, and only an active member qualifies.
 */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date = new Date(),
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return null;
  if (!isAwayAt(absence, at)) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;
  return absence.delegateUserId;
}

/** Where an assignment meant for `assigneeId` actually lands. */
export async function resolveAssignee(
  actor: Actor,
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actor.userId) return assigneeId;
  return (await findActiveDelegate(orgId, assigneeId)) ?? assigneeId;
}
